random.seed(1)
for y in range(0, H, 64): d.line([(0, y), (W, y)], fill=(80, 128, 154), width=2)
for x in range(0, W, 64): d.line([(x, 0), (x, H)], fill=(80, 128, 154), width=2)
for name, pts in LAND.items():
    poly = [P(*p) for p in pts]
    d.polygon(poly, fill=(222, 202, 150)); d.line(poly + [poly[0]], fill=(96, 66, 40), width=4)
for k in range(6000):
    x, y = random.randrange(W), random.randrange(H); c = im.getpixel((x, y))
    if c[0] > 150: d.point((x, y), fill=(c[0] - 18, c[1] - 18, c[2] - 14))
paper = Image.effect_noise((W, H), 18).convert("RGB")
im = Image.blend(im, Image.merge("RGB", [paper.split()[0]] * 3).point(lambda v: 128 + (v - 128) // 3), 0.08)
im.save("maps/worldmap.png"); print("map saved")
